var TABLE=[["bit","b",1.0], ["nibble","nibble",4.0], ["byte","B",8.0], ["kilobit","kb",1000.0], ["kilobyte","kB",8000.0], ["megabit","Mb",1000000.0], ["megabyte","MB",8000000.0], ["gigabit","Gb",1000000000.0], ["gigabyte","GB",8000000000.0], ["terabit","Tb",1000000000000.0], ["terabyte","TB",8000000000000.0], ["petabit","Pb",1000000000000000.0], ["petabyte","PB",8000000000000000.0], ["exabit","Eb",1e+18], ["exabyte","EB",8e+18], ["kibibit","Kib",1024.0], ["kibibyte","KiB",8192.0], ["mebibit","Mib",1048576.0], ["mebibyte","MiB",8388608.0], ["gibibit","Gib",1073741824.0], ["gibibyte","GiB",8589934592.0], ["tebibit","Tib",1099511627776.0], ["tebibyte","TiB",8796093022208.0], ["word","word",16.0], ["DVD capacity","reference",37600000000.0], ["Blu-ray capacity","reference",200000000000.0], ["Human genome","reference",6400000000.0], ["Library of Congress","reference",160000000000000.0]];
function toBase(v,name){name=String(name).toLowerCase();for(var i=0;i<TABLE.length;i++){if(TABLE[i][0].toLowerCase()===name||TABLE[i][1].toLowerCase()===name)return v*TABLE[i][2];}throw new Error("unknown unit: "+name);}
function convert(v,from,to){var b=toBase(v,from);to=String(to).toLowerCase();for(var i=0;i<TABLE.length;i++){if(TABLE[i][0].toLowerCase()===to||TABLE[i][1].toLowerCase()===to)return b/TABLE[i][2];}throw new Error("unknown unit: "+to);}
// demo: 1 DVD capacity expressed in every unit of this database
console.log(TABLE.map(function(u){return "1 DVD capacity = "+convert(1,"DVD capacity",u[0])+" "+u[0]+" ("+u[1]+")";}).join("\n"));

